import argparse, sys, importlib.util

# Mock torch and transformers so we can import just the argparse part
class MockModule:
    def __getattr__(self, name):
        return MockModule()
    def __call__(self, *a, **kw):
        return MockModule()

for mod in ['torch', 'torch.nn', 'torch.utils', 'torch.utils.data',
            'transformers', 'weighting', 'weighting.alpha_eff']:
    sys.modules[mod] = MockModule()

# Now extract parse_args by parsing the file
import ast
with open('training/pretrain_weighted.py') as f:
    source = f.read()

# Find the parse_args function and run it standalone
exec_globals = {'argparse': argparse, '__name__': '__main__'}
# Extract just parse_args
tree = ast.parse(source)
for node in ast.walk(tree):
    if isinstance(node, ast.FunctionDef) and node.name == 'parse_args':
        func_source = ast.get_source_segment(source, node)
        exec(func_source, exec_globals)
        break

sys.argv = ['pretrain_weighted.py', '--help']
try:
    exec_globals['parse_args']()
except SystemExit:
    pass
"
